PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS question_bank_sources (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  url TEXT NOT NULL,
  provider TEXT NOT NULL,
  source_kind TEXT NOT NULL,
  categories_json TEXT NOT NULL DEFAULT '[]',
  usage_mode TEXT NOT NULL DEFAULT 'reference_only',
  licence_note TEXT,
  enabled INTEGER NOT NULL DEFAULT 1,
  priority INTEGER NOT NULL DEFAULT 50,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS question_bank_items (
  question_id TEXT PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
  source_id TEXT REFERENCES question_bank_sources(id),
  category TEXT NOT NULL CHECK(category IN ('oral','reading_comprehension','cloze','writing')),
  subcategory TEXT NOT NULL,
  provenance TEXT NOT NULL DEFAULT 'original',
  source_reference TEXT,
  tags_json TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_qbank_category ON question_bank_items(category,subcategory);
CREATE INDEX IF NOT EXISTS idx_qbank_source ON question_bank_items(source_id);

CREATE TABLE IF NOT EXISTS specialised_sessions (
  id TEXT PRIMARY KEY,
  child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE,
  mode TEXT NOT NULL CHECK(mode IN ('practice','exam')),
  category TEXT NOT NULL CHECK(category IN ('oral','reading_comprehension','cloze','writing')),
  requested_count INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','evaluating','completed','abandoned')),
  score REAL,
  max_score REAL,
  started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  completed_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_specialised_sessions_child ON specialised_sessions(child_id,started_at);

CREATE TABLE IF NOT EXISTS specialised_session_items (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES specialised_sessions(id) ON DELETE CASCADE,
  question_id TEXT NOT NULL REFERENCES questions(id),
  item_order INTEGER NOT NULL,
  question_type TEXT NOT NULL,
  stem_json TEXT NOT NULL,
  answer_json TEXT NOT NULL,
  explanation_json TEXT,
  marks REAL NOT NULL DEFAULT 1,
  response_json TEXT,
  score REAL,
  max_score REAL,
  feedback_json TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','answered','evaluating','completed','failed')),
  generation_job_id TEXT,
  answered_at TEXT,
  completed_at TEXT,
  UNIQUE(session_id,item_order)
);
CREATE INDEX IF NOT EXISTS idx_specialised_items_session ON specialised_session_items(session_id,item_order);
