INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,source_content_id,curriculum_version_id,generation_model,marks) VALUES ('read-p5-otters-1','reading_mcq','P5','3','{"title":"City Otters","passage":"After years of cleaner waterways and habitat improvement, otters began appearing more often along Singapore’s rivers and reservoirs. Their return excited many residents, but it also created new challenges. Otters sometimes cross roads or enter fish ponds while searching for food. Wildlife groups therefore encourage people to observe them from a safe distance, keep food away from wild animals and avoid blocking an otter family’s path. These simple actions allow people and wildlife to share the city more safely.","prompt":"What is the main reason otters are seen more often in the city?","options":["Cleaner waterways and improved habitats","Residents feed them every day","Fish ponds were removed","Roads were closed"]}','{"correctOption":0}','{"text":"Cleaner waterways and habitat improvement supported their return."}','published',NULL,'SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5-r7','1');
