INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,source_content_id,curriculum_version_id,generation_model,marks) VALUES ('read-p5-space-1','reading_mcq','P5','3','{"title":"Exercise in Space","passage":"Astronauts living in space can float because they experience microgravity. Floating may look easy, but the human body changes when muscles and bones do not work against gravity in the usual way. To reduce these changes, astronauts exercise for about two hours each day using special machines. Some machines imitate running, while others provide resistance for strength training. Regular exercise helps astronauts remain strong enough to work in space and return safely to Earth.","prompt":"Why do astronauts exercise every day?","options":["To learn how to float","To reduce muscle and bone loss","To make the spacecraft move faster","To sleep more easily"]}','{"correctOption":1}','{"text":"Exercise helps reduce changes to muscles and bones."}','published',NULL,'SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5-r7','1');
