INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,source_content_id,curriculum_version_id,generation_model,marks) VALUES ('read-p6-mangrove-1','reading_mcq','P6','3','{"title":"Mangrove Defences","passage":"Mangrove forests grow where land and sea meet. Their tangled roots trap sediment and slow moving water. During storms, this network can reduce the energy of waves before the waves reach areas farther inland. Mangroves also provide nursery habitats for fish and other animals. However, mangroves are not a complete replacement for every form of coastal protection. Scientists often recommend combining healthy natural habitats with careful planning and, where necessary, engineered defences.","prompt":"How do mangrove roots help protect coasts?","options":["They increase wave energy","They trap sediment and slow water","They remove all seawater","They move storms away"]}','{"correctOption":1}','{"text":"The roots trap sediment and slow moving water."}','published',NULL,'SG-PRIMARY-ENGLISH-2020-PSLE-2026','seed-v0.5-r7','1');
