-- Bring earlier standalone Paper 2 questions into the Question Bank as well.
INSERT OR IGNORE INTO question_bank_items (question_id,source_id,category,subcategory,provenance,source_reference,tags_json)
SELECT q.id,'qsrc-internal',
  CASE WHEN q.question_type IN ('grammar_cloze','vocabulary_cloze','comprehension_cloze','grammar_mcq','vocabulary_mcq','editing_grammar','editing_spelling') THEN 'cloze' ELSE 'reading_comprehension' END,
  q.question_type,'original','Earlier English Mastery standalone bank item',json_array(q.school_level,q.question_type)
FROM questions q
WHERE q.status='published' AND q.source_content_id IS NULL
  AND q.question_type IN ('grammar_cloze','vocabulary_cloze','comprehension_cloze','grammar_mcq','vocabulary_mcq','editing_grammar','editing_spelling','open_comprehension','synthesis','visual_text');
